def runs(b, c):
    # list of (length, lowest_row, highest_row) of vertical runs of opponent stones in column c
    out = []
    r = 0
    h = b.heights[c]
    while r < h:
        if b.grid[r][c] == 2:
            s = r
            while r < h and b.grid[r][c] == 2:
                r += 1
            out.append((r - s, s, r - 1))
        else:
            r += 1
    return out

